# ==============================================================================
# GENERAL FITTING ENGINE (fit.R)
# DO NOT EDIT THIS FILE! Change your settings in '1_run_pipeline.R'.
# ==============================================================================

Sys.setenv(LC_ALL = "C")
Sys.setenv(LANG = "C")
suppressPackageStartupMessages({
  library(Rcpp); library(DEoptim); library(dplyr); library(RcppZiggurat); library(data.table); library(here)
  source(here("R", "helper_functions.R"))
  sourceCpp(here("R", "models.cpp"))
})

# ==============================================================================
# 1. READ ARGUMENTS
# ==============================================================================
args <- commandArgs(trailingOnly = TRUE)
if (length(args) < 2) stop("Engine requires 2 arguments: Subject_Index and Config_Path")

subj_arg    <- args[1]
CONFIG_PATH <- args[2]

# ==============================================================================
# 2. LOAD SETTINGS FROM CONTROLLER
# ==============================================================================
load(CONFIG_PATH)

# Determine Subject Index
if (subj_arg == "GROUP") {
  SUBJECT_IDX <- NULL
} else {
  SUBJECT_IDX <- as.numeric(subj_arg)
}

# Inspect Model Capabilities
model_info <- get_model_info(MODEL_NAME)

# ==============================================================================
# 3. PIPELINE INTERNAL SETTINGS & ADAPTIVE CONSTANTS
# ==============================================================================
COST_METHOD <- "gsquare"
TRACE       <- ITER_MAX / 10 
POP_SCALE   <- 10
N_PRED      <- 10000

# Set default simulation constants matching the model scale
sim_constants <- list(
  ntrials = 5000, 
  s       = model_info$default_s, 
  dt      = model_info$default_dt
)

# Apply user overrides if specified
if (exists("SIM_CONSTANTS") && is.list(SIM_CONSTANTS) && length(SIM_CONSTANTS) > 0) {
  for (nm in names(SIM_CONSTANTS)) sim_constants[[nm]] <- SIM_CONSTANTS[[nm]]
}

# Auto-detect experimental conditions to split G-Square likelihood blocks safely
vars_in_formulas <- unique(unlist(lapply(VARYING_PARAMS, all.vars)))
missing_conds <- setdiff(vars_in_formulas, CONDITIONS)
if (length(missing_conds) > 0) {
  stop(paste("\n[DESIGN ERROR] You used a variable in VARYING_PARAMS that is not listed in CONDITIONS.",
             "\nPlease add:", paste(missing_conds, collapse = ", "), "to the CONDITIONS list."))
}

# Build FIT_TARGETS dynamically based on model capabilities
primary_split <- c("acc", CONDITIONS)
if (model_info$has_conflict) {
  primary_split <- unique(c("acc", "congruency", CONDITIONS))
}

FIT_TARGETS <- list(
  # Decision RT shape split
  list(rt_col = "rt", split_cols = primary_split, weight = 1)
)

if (model_info$has_confidence) {
  # Confidence RT shape split
  FIT_TARGETS[[length(FIT_TARGETS) + 1]] <- list(rt_col = "rtconf", split_cols = primary_split, weight = 1)
  # Pure confidence rating proportions
  FIT_TARGETS[[length(FIT_TARGETS) + 1]] <- list(rt_col = "cj", split_cols = unique(c("acc", "cj", CONDITIONS)), weight = 1)
}

print(paste("Active Configuration -> Subject:", ifelse(is.null(SUBJECT_IDX), "Group", SUBJECT_IDX), 
            "| Model:", MODEL_NAME, sprintf("(Time: %s, s=%.1f, dt=%.3f)", model_info$time_unit, sim_constants$s, sim_constants$dt)))

# ==============================================================================
# 4. LOADING AND FILTERING DATA
# ==============================================================================
DATA_FILE <- here("data", DATA_NAME) 
if (!file.exists(DATA_FILE)) stop(paste("File not found:", DATA_FILE))

if (grepl("\\.rds$", DATA_FILE, ignore.case = TRUE)) {
  raw_data <- readRDS(DATA_FILE)
} else {
  raw_data <- as.data.frame(data.table::fread(DATA_FILE))
}
OUTPUT_DIR <- here("results", OUTPUT_FOLDER)

# Dynamic Required Column Check
required_cols <- c("rt", "acc", SUBJECT_COL)
if (model_info$has_conflict)   required_cols <- c(required_cols, "congruency")
if (model_info$has_confidence) required_cols <- c(required_cols, "rtconf", "cj")

missing_cols <- setdiff(required_cols, names(raw_data))
if (length(missing_cols) > 0) {
  stop(paste0("\n[DATA ERROR] Model '", MODEL_NAME, "' requires the following missing column(s): ", 
              paste(missing_cols, collapse = ", "), 
              "\nPlease ensure your dataset contains these columns."))
}

# Ensure numeric RTs
raw_data$rt <- as.numeric(as.character(raw_data$rt))
if (model_info$has_confidence) {
  raw_data$rtconf <- as.numeric(as.character(raw_data$rtconf))
}

# Handle subject filtering
if (!is.null(SUBJECT_IDX)) {
  all_subjects <- sort(unique(raw_data[[SUBJECT_COL]]))
  target_sub_id <- all_subjects[SUBJECT_IDX]
  SUBJECT_ID_VAL <- target_sub_id
  observations <- raw_data[raw_data[[SUBJECT_COL]] == target_sub_id, ]
  print(paste("Filtering Subject Index:", SUBJECT_IDX, "-> ID:", target_sub_id))
} else {
  observations <- raw_data
  SUBJECT_ID_VAL <- "GROUP"
  print("Fitting Group/All Data.")
}

# --- Strict Guardrail: Filter empirical observations to completed valid trials ---
observations <- observations[!is.na(observations$acc) & observations$acc %in% c(0, 1), ]
observations <- observations[!is.na(observations$rt) & is.finite(observations$rt) & observations$rt > 0, ]

if (model_info$has_conflict) {
  observations <- observations[!is.na(observations$congruency) & observations$congruency %in% c(-1, 1), ]
}
if (model_info$has_confidence) {
  observations <- observations[!is.na(observations$rtconf) & is.finite(observations$rtconf) & observations$rtconf > 0, ]
  observations <- observations[!is.na(observations$cj), ]
}

if (nrow(observations) == 0) stop("No valid trials found for the selected subject...")

# ==============================================================================
# 5. CONFIGURE PARAMETER SPACE
# ==============================================================================
config <- get_param_config(MODEL_NAME, VARYING_PARAMS, observations)
config <- fix_parameters(config, FIXED_PARAMS)
fit_constants <- c(config$fixed, sim_constants)

# ==============================================================================
# 6. STANDARDIZATION OF THE FACTORS
# ==============================================================================
observations$acc <- factor(as.numeric(as.character(observations$acc)), levels = c(0, 1))

# Conflict Standardization: Congruency levels (-1, 1)
if (model_info$has_conflict) {
  if (!all(observations$congruency %in% c(-1, 1), na.rm = TRUE)) {
    stop("\n[DATA ERROR] For conflict models, 'congruency' must be coded as -1 (Incongruent) and 1 (Congruent).")
  }
  observations$congruency <- factor(observations$congruency, levels = c(-1, 1))
}

# Confidence Standardization: 0/1 for binary, 1-6 for 6-point
if (model_info$has_confidence) {
  if (MODEL_NAME == "FCB_cj2") {
    if (!all(observations$cj %in% c(0, 1), na.rm = TRUE)) {
      stop("\n[DATA ERROR] For FCB_cj2, 'cj' must be coded as 0 (Low) and 1 (High).")
    }
    observations$cj <- factor(observations$cj, levels = 0:1)
  } else if (MODEL_NAME == "FCB_cj6") {
    if (!all(observations$cj %in% 1:6, na.rm = TRUE)) {
      stop("\n[DATA ERROR] For FCB_cj6, 'cj' must contain ratings in the 1-6 range.")
    }
    observations$cj <- factor(observations$cj, levels = 1:6)
  }
}

# Ensure condition columns are factors
if (!is.null(CONDITIONS)) {
  for (col_name in CONDITIONS) {
    if (col_name %in% names(raw_data)) {
      master_lvls <- sort(unique(raw_data[[col_name]]))
      observations[[col_name]] <- factor(observations[[col_name]], levels = master_lvls)
      cat(sprintf("Factorized column: %s | Intercept baseline: %s\n", col_name, master_lvls[1]))
    }
  }
}

print(paste("Observations ready:", nrow(observations), "trials."))

# ==============================================================================
# 7. RUN OPTIMIZATION
# ==============================================================================
ctrl <- DEoptim.control(
  itermax = ITER_MAX, 
  trace   = TRACE,
  NP      = POP_SCALE * length(config$lower),
  parallelType = USE_CORES, 
  packages     = c("Rcpp", "RcppZiggurat", "dplyr"),
  parVar       = c("FIT_TARGETS", "VARYING_PARAMS", "MODEL_NAME") 
)

print(paste("Starting DEoptim on", length(config$lower), "parameters..."))
start_time <- Sys.time()

cat("\nParameter mapping overview:")
for (p in names(get_model_params(MODEL_NAME))) {
  if (p %in% names(VARYING_PARAMS)) {
    cat(sprintf("\n  [VARYING] %-10s -> Formula: %s", p, deparse(VARYING_PARAMS[[p]])))
  } else if (p %in% names(fit_constants)) {
    cat(sprintf("\n  [FIXED]   %-10s -> Value: %s", p, fit_constants[[p]]))
  } else {
    cat(sprintf("\n  [SHARED]  %-10s -> Estimated globally", p))
  }
}
cat("\n\nStarting optimization...\n")

cat("\n==================================================\n")
cat("FREE PARAMETERS (Optimizing):\n")
cat(sprintf("  %-4s %-25s %-20s\n", "Idx", "Parameter Name", "Bounds [Min, Max]"))
cat("  --------------------------------------------------\n")
for (i in seq_along(config$lower)) {
  cat(sprintf("  [%02d] %-25s [%.4f, %.4f]\n", i, config$names[i], config$lower[i], config$upper[i]))
}
cat("==================================================\n")

result <- DEoptim(
  fn = objective_function, 
  lower = config$lower, 
  upper = config$upper,
  observations   = observations,
  param_names    = config$names,
  constants      = fit_constants,
  model_fun      = MODEL_NAME, 
  targets        = FIT_TARGETS, 
  cost_method    = COST_METHOD,  
  varying_params = VARYING_PARAMS,
  conditions     = CONDITIONS,
  control        = ctrl
)

duration <- Sys.time() - start_time
print(paste("Optimization finished in:", round(duration, 2), units(duration)))

# ==============================================================================
# 8. GENERATE HIGH RESOLUTION PREDICTIONS
# ==============================================================================
print(paste("Generating best-fit predictions with", N_PRED, "trials..."))

best_params <- result$optim$bestmem
best_betas  <- NULL

is_regression <- any(sapply(VARYING_PARAMS, function(x) inherits(x, "formula")))

if (is_regression) {
  cat("Translating Regression Betas to Marginal Cell Means...\n")
  best_betas <- best_params 
  reconstructed_params <- c()
  
  all_cond_cols <- unique(unlist(lapply(VARYING_PARAMS, all.vars)))
  cond_grid <- unique(observations[, all_cond_cols, drop = FALSE])
  p_base_names <- names(get_model_params(MODEL_NAME))
  
  for (i in 1:nrow(cond_grid)) {
    current_cell <- cond_grid[i, , drop = FALSE]
    p_lvl <- pluck_params(best_betas, fit_constants, current_cell, VARYING_PARAMS, MODEL_NAME)
    
    for (p in p_base_names) {
      if (p %in% names(VARYING_PARAMS)) {
        p_formula <- VARYING_PARAMS[[p]]
        p_vars <- all.vars(p_formula)
        if (length(p_vars) > 0) {
          cell_strings <- paste(p_vars, unlist(current_cell[, p_vars, drop = FALSE]), sep = "_")
          p_lvl_val <- paste(cell_strings, collapse = ".")
          reconstructed_params[paste0(p, ":", p_lvl_val)] <- p_lvl[[p]]
        } else {
          reconstructed_params[p] <- p_lvl[[p]]
        }
      } else if (!p %in% names(fit_constants)) {
        reconstructed_params[p] <- p_lvl[[p]]
      }
    }
  }
  best_params <- reconstructed_params[!duplicated(names(reconstructed_params))]
}

pred_constants <- fit_constants
pred_constants$ntrials <- N_PRED

sim_varying_params <- list()
for (p in names(VARYING_PARAMS)) sim_varying_params[[p]] <- all.vars(VARYING_PARAMS[[p]])

final_predictions <- objective_function(
  params         = best_params,
  observations   = observations,
  param_names    = names(best_params),
  constants      = pred_constants,
  model_fun      = MODEL_NAME,
  targets        = FIT_TARGETS, 
  varying_params = sim_varying_params,
  conditions     = CONDITIONS,
  returnFit      = 0 
)

for (col in names(observations)) {
  if (col %in% names(final_predictions) && is.factor(observations[[col]])) {
    final_predictions[[col]] <- factor(final_predictions[[col]], levels = levels(observations[[col]]))
  }
}

final_proportions <- objective_function(
  params         = best_params,
  observations   = observations,
  param_names    = names(best_params),
  constants      = pred_constants,
  model_fun      = MODEL_NAME,
  targets        = FIT_TARGETS, 
  varying_params = sim_varying_params,
  conditions     = CONDITIONS, 
  returnFit      = 2
)

n_bins_total <- attr(result$optim$bestval, "n_bins")
if (is.null(n_bins_total)) { 
  n_bins_total <- sum(unlist(lapply(final_proportions, function(target_list) {
    sum(sapply(target_list, function(level) length(level$obs)))
  })))
}

# ==============================================================================
# 9. REPORTING & SAVING
# ==============================================================================
n_free_params <- length(config$lower) 
fit_metrics <- list(
  n_observations = nrow(observations),
  n_free_params  = n_free_params,
  n_bins         = n_bins_total,
  best_cost      = result$optim$bestval,
  bic = result$optim$bestval + n_free_params * log(nrow(observations)),
  aic = result$optim$bestval + 2 * n_free_params
)

fit_output <- list(
  best_params  = best_params,
  best_betas   = best_betas,  
  fit_metrics  = fit_metrics,
  optim_full   = result,
  param_info   = config,
  constants    = fit_constants,
  targets      = FIT_TARGETS,
  cost_method  = COST_METHOD,
  observations = observations,
  predictions  = final_predictions,
  final_proportions = final_proportions,
  info = list(
    model          = MODEL_NAME,
    timestamp      = Sys.time(),
    subject        = SUBJECT_ID_VAL,
    varying_params = VARYING_PARAMS,
    conditions     = CONDITIONS
  )
)

if (!dir.exists(OUTPUT_DIR)) dir.create(OUTPUT_DIR, recursive = TRUE)
file_base <- paste0(MODEL_NAME, "_FIT_sub-", SUBJECT_ID_VAL, "_", format(Sys.time(), "%Y%m%d_%H%M%S"))
saveRDS(fit_output, file.path(OUTPUT_DIR, paste0(file_base, ".rds")))
print(paste("Best Cost:", round(fit_metrics$best_cost, 4)))

# ==============================================================================
# 10. VISUALIZATION (Adaptive per Model Family)
# ==============================================================================
cat("\nGenerating diagnostic reports...\n")

pdf_path <- file.path(OUTPUT_DIR, paste0(file_base, ".pdf"))
pdf(file = pdf_path, width = 10, height = 6)

# 1. Primary Decision RT (Faceted by Congruency for Conflict Models)
facet_col <- if (model_info$has_conflict) "congruency" else NULL
plot_dist(obs = fit_output$observations, pred = fit_output$predictions, 
          val_col = "rt", facet_col = facet_col, split_by_acc = TRUE, main_title = "Decision RT")

# 2. Conflict Diagnostics
if (model_info$has_conflict) {
  # Conditional Accuracy Function (CAF)
  plot_conditional_function(obs = fit_output$observations, pred = fit_output$predictions, 
                            x_col = "rt", y_col = "acc", group_col = "congruency", main_title = "Conditional Accuracy Function (CAF)")
  # Delta Plot
  plot_delta(obs = fit_output$observations, pred = fit_output$predictions, main_title = "Delta Plot")
  # Mechanism Trajectory (if DMC)
  if (MODEL_NAME == "DMC") {
    plot_dmc_mechanism(params = fit_output$best_params, constants = fit_output$constants, main_title = "DMC Mechanism")
  }
}

# 3. Confidence Diagnostics
if (model_info$has_confidence) {
  plot_dist(obs = fit_output$observations, pred = fit_output$predictions, 
            val_col = "rtconf", split_by_acc = TRUE, main_title = "Confidence RT")
  p_cj <- plot_cj_distribution(fit_output$observations, fit_output$predictions)
  if (!is.null(p_cj)) print(p_cj)
}

dev.off() 
cat(sprintf("PDF Report saved to: %s\n", pdf_path))
